const fn = new Function(code + "\nreturn { createLoader, loadDashboard, withTimeout };");
const { createLoader, loadDashboard, withTimeout } = fn();
let calls = 0;
const loader = createLoader(async (key) => { calls++; await new Promise((r) => setTimeout(r, 10)); return key + "-data"; });
const [a, b] = await Promise.all([loader.load("x"), loader.load("x")]);
if (a !== "x-data" || b !== "x-data") throw new Error("Both loads should resolve with the fetched value.");
if (calls !== 1) throw new Error("Concurrent loads of the same key must share one flight (1 call, got " + calls + ").");
const c = await loader.load("x");
if (c !== "x-data") throw new Error("Later loads still return the cached promise's value.");
loader.reset();
await loader.load("x");
if (calls !== 2) throw new Error("After reset, loading again must re-fetch.");

const fn = new Function(code + "\nreturn { createLoader, loadDashboard, withTimeout };");
const { createLoader, loadDashboard, withTimeout } = fn();
const ok1 = () => Promise.resolve(1);
const ok2 = () => Promise.resolve(2);
const bad = () => Promise.reject(new Error("boom"));
const out = await loadDashboard([ok1, bad, ok2]);
if (out.loaded.join() !== "1,2") throw new Error("loaded should be fulfilled values in source order.");
if (out.failed.length !== 1) throw new Error("failed should hold the single rejection reason.");
const allBad = await loadDashboard([bad, bad]);
if (allBad.loaded.length !== 0 || allBad.failed.length !== 2) throw new Error("loadDashboard never rejects, even when every source fails.");

const fn = new Function(code + "\nreturn { createLoader, loadDashboard, withTimeout };");
const { createLoader, loadDashboard, withTimeout } = fn();
const fast = withTimeout(Promise.resolve("quick"), 50, "fallback");
if ((await fast) !== "quick") throw new Error("A promise that fulfills in time resolves with its value.");
const slow = withTimeout(new Promise((r) => setTimeout(() => r("late"), 80)), 20, "gave-up");
if ((await slow) !== "gave-up") throw new Error("A promise that misses the deadline settles with the fallback.");
